'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={tab:'overview',user:null,jobs:[],jobId:null,report:null,conversations:[],slots:[],talents:[],exams:[],exam:null,attempts:[],attempt:null,examView:null,sitting:null,publicExams:[]};
const titles={overview:'Visão geral',jobs:'Gestão de vagas',ranking:'Análise de currículos',exams:'Provas e avaliações',whatsapp:'Triagem no WhatsApp',calendar:'Agenda de entrevistas',talents:'Talentos internos',accounts:'Usu\u00e1rios e acessos'};
const symbols={overview:'▦',jobs:'▤',ranking:'✧',exams:'✎',whatsapp:'◉',calendar:'▦',talents:'♧',accounts:'⚿'};
function brand(){return '<div class="brand"><div class="brand-mark">DDM</div><div><strong>Pessoas</strong><small>Grupo DDM</small></div></div>';}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,7000);}
async function api(path,options={}){const res=await fetch('/api/v1'+path,{...options,headers:{'X-Requested-With':'DDM-RH',...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...options.headers}});let data;try{data=await res.json();}catch{throw Error('Resposta do servidor indisponível.');}if(!res.ok){if(res.status===401&&state.user){state.user=null;login();}throw Error(typeof data.detail==='string'?data.detail:'Verifique os campos informados.');}return data;}
const json=(method,body)=>({method,body:JSON.stringify(body)});
function modal(title,body){$('#dialog-content').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button data-action="close" class="quiet" aria-label="Fechar">✕</button></div>${body}`;$('#dialog').showModal();}
function close(){$('#dialog').close();}
function empty(title,text,action='',label=''){return `<div class="empty"><span class="circle-icon">↗</span><strong>${esc(title)}</strong><p>${esc(text)}</p>${action?`<button class="primary" data-action="${action}">${label}</button>`:''}</div>`;}
const pill=(text,style='')=>`<span class="pill ${style}">${esc(text)}</span>`;
const date=value=>value?new Date(value).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'—';
const heading=(title,description,action='')=>`<div class="heading"><div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;
const currentJob=()=>state.jobs.find(j=>j.id===Number(state.jobId));
function jobOptions(){return state.jobs.map(j=>`<option value="${j.id}" ${Number(state.jobId)===j.id?'selected':''}>${esc(j.title)}</option>`).join('');}
function shell(){$('#app').innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="nav-label">Workspace do RH</div><nav class="nav" aria-label="Navegação principal">${Object.entries(titles).filter(([key])=>key!=='accounts'||state.user?.role==='admin').map(([key,label])=>`<button data-action="nav" data-tab="${key}" class="${state.tab===key?'active':''}"><span aria-hidden="true">${symbols[key]}</span> ${label}</button>`).join('')}</nav><div class="sidebar-bottom"><a class="portal-link" href="/interno" target="_blank" rel="noopener">Portal de vagas internas ↗</a><div class="user"><div class="avatar">${esc(state.user.name.slice(0,2).toUpperCase())}</div><div><strong>${esc(state.user.name)}</strong><small>Recursos Humanos</small></div></div></div></aside><div><header class="topbar"><span>Workspace &nbsp; / &nbsp; <strong>${titles[state.tab]}</strong></span><div class="actions"><span class="date">${new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'})}</span><button class="quiet small" data-action="my-password">Minha senha</button><button class="quiet small" data-action="logout">Sair</button></div></header><main class="main" id="main"><p>Carregando…</p></main></div></div>`;}
async function loadCommon(){[state.jobs,state.integrations]=await Promise.all([api('/jobs'),api('/settings/integrations')]);if(!state.jobs.some(j=>j.id===Number(state.jobId)))state.jobId=state.jobs[0]?.id;}
async function navigate(tab){state.tab=tab;shell();try{await loadCommon();await render();}catch(e){if($('#main'))$('#main').innerHTML=empty('Não foi possível carregar',e.message,'retry','Tentar novamente');}}
async function render(){const main=$('#main');if(!main)return;
if(state.tab==='overview'){
const [reports,talents,conversations]=await Promise.all([Promise.all(state.jobs.map(j=>api(`/jobs/${j.id}/screenings`))),api('/talents'),api('/conversations')]);
main.innerHTML=heading('Pessoas certas. Novas possibilidades.','Acompanhe seu recrutamento, da primeira análise à próxima conversa.','<button class="primary" data-action="new-job">＋ Nova vaga</button>')+`<section class="hero"><div><div class="eyebrow">Talento encontra oportunidade</div><h2>Mais clareza para contratar.<br>Mais espaço para crescer.</h2><p>Reúna requisitos, currículos e conversas em um só lugar. A tecnologia apoia a análise; o RH conduz cada decisão.</p></div><div class="hero-action"><button class="primary" data-action="nav" data-tab="ranking">Analisar candidatos ↗</button><small>Uma jornada, do início ao encontro.</small></div></section><div class="metrics"><div class="metric accent"><span>Vagas cadastradas</span><strong>${state.jobs.length}</strong><small>${state.jobs.filter(j=>j.internal&&j.published).length} no portal interno</small></div><div class="metric"><span>Currículos recebidos</span><strong>${reports.reduce((s,r)=>s+r.total_candidates,0)}</strong><small>Disponíveis para análise</small></div><div class="metric"><span>Conversas de triagem</span><strong>${conversations.length}</strong><small>${conversations.filter(c=>c.status==='completed').length} aguardando avaliação</small></div><div class="metric"><span>Talentos internos</span><strong>${talents.length}</strong><small>Colaboradores no banco de talentos</small></div></div><div class="grid"><section class="card"><div class="card-head"><div><h2>Suas oportunidades</h2><p>Próximos passos de cada processo seletivo</p></div><button class="quiet small" data-action="nav" data-tab="jobs">Ver todas →</button></div>${jobsList(state.jobs.slice(0,4))}</section><section class="card"><h2>Uma seleção bem acompanhada</h2><p class="text-small">Seu fluxo de recrutamento</p>${[['Requisitos claros','Importe a vaga e revise os critérios.'],['Análise com evidências','Compare currículos e valide os melhores perfis.'],['Conversas que aproximam','Personalize a triagem pelo WhatsApp.'],['O próximo encontro','Reserve um horário na agenda do RH.']].map((v,i)=>`<div class="flow"><div class="flow-num">0${i+1}</div><div><strong>${v[0]}</strong><p>${v[1]}</p></div></div>`).join('')}</section></div><div class="notice info">${state.integrations.ai.active?'OpenAI configurada. Análises executadas quando solicitadas.':'Análise local disponível. Configure a OpenAI no servidor para habilitar a avaliação por IA.'}</div>`;
}else if(state.tab==='jobs'){main.innerHTML=heading('Oportunidades em movimento','Defina requisitos, posições e a experiência de triagem.','<button class="primary" data-action="new-job">＋ Nova vaga</button>')+`<div class="card"><div class="toolbar"><input id="job-search" type="search" placeholder="Buscar vaga por título ou local" aria-label="Buscar vagas"></div><div id="job-list">${jobsList(state.jobs)}</div></div>`;
}else if(state.tab==='ranking'){main.innerHTML=heading('Uma análise que você pode explicar','Cada requisito comparado ao currículo, com evidências para apoiar sua decisão.')+(state.jobs.length?`<div class="card"><div class="toolbar"><label>Processo seletivo<select id="ranking-job">${jobOptions()}</select></label><button data-action="edit-job" data-id="${state.jobId}">Revisar vaga</button><label class="button">↑ Incluir currículos<input type="file" id="resume-upload" accept=".pdf,.docx" multiple hidden></label><button class="primary" data-action="run-analysis">✧ Executar análise</button></div><p class="help">PDF ou DOCX, até 8 MB por arquivo e 30 por envio. Abrir esta tela não faz novas chamadas à IA.</p></div><div id="ranking-content">Carregando resultados…</div>`:empty('Cadastre uma vaga primeiro','Os requisitos são a base para comparar os currículos.','new-job','Cadastrar vaga'));if(state.jobs.length){state.report=await api(`/jobs/${state.jobId}/screenings`);renderRanking();}
}else if(state.tab==='exams'){await renderExams();
}else if(state.tab==='accounts'){await renderAccounts();
}else if(state.tab==='talents'){state.talents=await api('/talents');main.innerHTML=heading('O próximo passo começa por dentro','Banco de talentos dos colaboradores e candidaturas internas.','<a class="button primary" href="/interno" target="_blank" rel="noopener">Portal público ↗</a>')+`<div class="notice info">A inscrição é pública. Currículos e dados ficam disponíveis apenas para o RH autenticado. A matrícula informada deve ser validada pela equipe.</div><div class="card"><h2>${state.talents.length} colaborador(es) no banco</h2><div class="toolbar"><input id="talent-search" type="search" placeholder="Buscar nome, departamento, cargo ou matrícula" aria-label="Buscar talentos"></div><div id="talent-list">${talentList(state.talents)}</div></div>`;
}else if(state.tab==='whatsapp'){state.conversations=await api('/conversations');main.innerHTML=heading('Boas conversas, melhores conexões','Revise as mensagens e acompanhe cada resposta da triagem.')+`<div class="notice">${esc(state.integrations.whatsapp.status)}. ${state.integrations.whatsapp.automatic?'Envio automático habilitado; depende do processador da fila ativo.':'As mensagens só são enviadas ao clicar em Enviar. Respostas ficam na fila para envio pelo operador.'}</div>${state.conversations.length?state.conversations.map(conversationCard).join(''):empty('Nenhuma conversa iniciada','Selecione candidatos na análise e prepare as convocações.','go-ranking','Abrir análise de currículos')}`;
}else if(state.tab==='calendar'){[state.slots,state.conversations]=await Promise.all([api('/calendar/slots'),api('/conversations')]);main.innerHTML=heading('Encontros que abrem caminhos','Disponibilidade do RH e entrevistas. Horários no seu fuso local.','<button class="primary" data-action="new-slot">＋ Disponibilizar horário</button>')+`<div class="notice info">${esc(state.integrations.calendar.status)}. Quando configurado, o Outlook é consultado antes de disponibilizar e reservar horários.</div><div class="card">${state.slots.length?state.slots.map(s=>{const c=state.conversations.find(c=>c.id===s.conversation_id);return `<div class="row"><div><strong>${date(s.starts_at)} — ${new Date(s.ends_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</strong><p>${esc(s.recruiter)} · ${esc(s.location)}${c?' · '+esc(c.name):''}</p></div>${s.conversation_id?pill('Entrevista marcada','green'):new Date(s.starts_at)<=new Date()?pill('Encerrado'):`<button class="small" data-action="book-slot" data-id="${s.id}">Reservar entrevista</button>`}</div>`;}).join(''):empty('Sua agenda começa com um horário','Disponibilize os melhores dias para receber candidatos.','new-slot','Adicionar disponibilidade')}</div>`;
}}
function jobsList(jobs){return jobs.length?jobs.map(j=>`<div class="row"><div><strong>${esc(j.title)}</strong><p>${esc(j.location||'Local a confirmar')} · ${j.openings?j.openings+' posição(ões)':'Quantidade a confirmar'} · ${j.requirements.length} requisitos</p></div><div class="actions">${pill(j.internal?'Interna':'Externa',j.internal?'orange':'')}${j.internal?pill(j.published?'Publicada':'Rascunho',j.published?'green':''):''}<button class="small" data-action="edit-job" data-id="${j.id}">Editar</button><button class="small" data-action="analyze-job" data-id="${j.id}">Candidatos →</button><button class="small danger" data-action="delete-job" data-id="${j.id}" data-title="${esc(j.title)}">Excluir</button></div></div>`).join(''):empty('Seu próximo talento começa aqui','Cadastre uma vaga ou importe a descrição pela URL.','new-job','Cadastrar primeira vaga');}
function talentList(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Colaborador</th><th>Departamento / cargo</th><th>Candidaturas</th><th>Cadastro</th><th></th></tr></thead><tbody>${rows.map(t=>`<tr><td><strong>${esc(t.name)}</strong>${esc(t.email)}<br>${esc(t.phone)} · Matrícula ${esc(t.employee_id)}</td><td>${esc(t.department)}<br>${esc(t.current_role)}</td><td>${t.applications.map(a=>esc(a.title)).join('<br>')||'Banco de talentos'}</td><td>${date(t.created_at)}</td><td><a class="button small" href="/api/v1/talents/${t.id}/resume">Currículo ↓</a></td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum colaborador encontrado','Compartilhe o link do portal interno com sua equipe.');}
function renderRanking(){const r=state.report,j=currentJob();$('#ranking-content').innerHTML=`${r.stale?'<div class="notice">Execute ou atualize a análise. Resultados anteriores não podem ser convocados quando os requisitos ou currículos mudam.</div>':''}${!j.openings?'<div class="notice">Confirme a quantidade de posições ao editar a vaga antes de preparar convocações.</div>':''}<div class="metrics"><div class="metric"><span>Currículos</span><strong>${r.total_candidates}</strong><small>Neste processo</small></div><div class="metric"><span>Posições disponíveis</span><strong>${j.openings||'—'}</strong><small>Limite de convocações</small></div><div class="metric"><span>Alta aderência</span><strong>${r.high_match_count}</strong><small>80 pontos ou mais</small></div><div class="metric"><span>Última análise</span><strong class="text-small">${r.analyzed_at?date(r.analyzed_at+'Z'):'Pendente'}</strong><small>Resultados salvos</small></div></div><section class="card"><div class="card-head"><div><h2>Ranking de candidatos</h2><p>Ordenado por aderência. Informações ausentes devem ser confirmadas.</p></div></div><div class="toolbar"><input id="ranking-search" type="search" placeholder="Buscar candidato" aria-label="Buscar candidato"><button data-action="select-best" ${r.stale||!j.openings?'disabled':''}>Selecionar melhores (${j.openings||'—'})</button><button class="primary" data-action="prepare-shortlist" ${r.stale||!j.openings?'disabled':''}>Preparar convocações</button></div><div id="ranking-list">${rankingList(r.results)}</div></section>`;}
function rankingList(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th></th><th>Candidato</th><th>Aderência</th><th>Prova</th><th>Obrigatórios</th><th>Origem</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><input type="checkbox" class="candidate-select" value="${r.candidate_id}" aria-label="Selecionar ${esc(r.name)}" ${state.report.stale?'disabled':''}></td><td><strong>${esc(r.name)}</strong>${esc(r.phone||'Telefone a confirmar')}</td><td><span class="score">${r.score.toFixed(1)} / 100</span><div class="bar"><i style="width:${Math.min(100,r.score)}%"></i></div></td><td>${examCell(r)}</td><td>${esc(r.mandatory_matched)}</td><td>${pill(r.evidences?.source==='openai'?'OpenAI':'Local · preliminar',r.evidences?.source==='openai'?'green':'orange')}</td><td class="actions"><button class="small" data-action="candidate" data-id="${r.id}">Ver análise →</button><button class="small danger" data-action="delete-resume" data-id="${r.id}" data-name="${esc(r.name)}">Excluir</button></td></tr>`).join('')}</tbody></table></div>`:empty('Os currículos ainda não foram analisados',state.report.total_candidates?'Clique em Executar análise para comparar os currículos.':'Inclua os currículos usando o botão acima.');}
const statusNames={awaiting_consent:'Aguardando aceite',screening:'Em triagem',completed:'Triagem concluída',opted_out:'Contato encerrado',interview_scheduled:'Entrevista marcada',pending:'Na fila',sending:'Enviando',accepted:'Aceita pelo provedor',uncertain:'Conferir no provedor',cancelled:'Cancelada'};
function conversationCard(c){return `<section class="card conversation"><div class="card-head"><div><h2>${esc(c.name)}</h2><p>${esc(c.job)} · ${esc(c.phone)}</p></div>${pill(statusNames[c.status]||c.status,c.status==='completed'?'green':'')}</div>${c.answers.map(a=>`<div class="bubble answer"><strong>${esc(a.question)}</strong><br>${esc(a.answer)}</div>`).join('')}${c.messages.map(m=>`<div class="bubble">${esc(m.content)}<div class="actions">${pill(statusNames[m.status]||m.status)}${m.status==='pending'?`<button class="small" data-action="send-message" data-id="${m.id}" ${!state.integrations.whatsapp.configured?'disabled':''}>Enviar</button>`:''}${m.error?`<span class="error">${esc(m.error)}</span>`:''}</div></div>`).join('')}</section>`;}
function requirementRow(r={category:'mandatory',title:'',weight:1}){return `<div class="req"><select aria-label="Categoria do requisito" class="req-category">${Object.entries({mandatory:'Obrigatório',desirable:'Desejável',experience:'Experiência',competency:'Competência'}).map(([v,l])=>`<option value="${v}" ${r.category===v?'selected':''}>${l}</option>`).join('')}</select><input class="req-title" aria-label="Descrição do requisito" value="${esc(r.title)}" required maxlength="500" placeholder="Ex.: Excel intermediário"><input class="req-weight" aria-label="Peso" type="number" min="0.1" max="10" step="0.1" value="${r.weight||1}"><button type="button" class="quiet" data-action="remove-req" aria-label="Remover requisito">×</button></div>`;}
function editJob(id){const j=state.jobs.find(j=>j.id===Number(id))||{};modal(j.id?'Editar oportunidade':'Uma nova oportunidade',`<form id="job-form" data-id="${j.id||''}"><div class="notice info">Importe pela URL ou preencha manualmente. Revise requisitos e quantidade antes de salvar.</div><div class="split"><label>URL da vaga<input name="source_url" type="url" placeholder="https://…" value="${esc(j.source_url||'')}"></label><div><button type="button" data-action="extract-url">Importar requisitos da URL ↗</button></div></div><label>Título da vaga<input name="title" required maxlength="190" value="${esc(j.title||'')}" placeholder="Ex.: Analista de Recursos Humanos"></label><label>Descrição e requisitos<textarea name="description" required rows="5" maxlength="40000">${esc(j.description||'')}</textarea></label><button type="button" data-action="extract-text">Extrair requisitos deste texto</button><div class="split"><label>Quantidade de posições<input name="openings" type="number" min="1" max="10000" placeholder="Confirmar na descrição" value="${j.openings||''}"></label><label>Local / modalidade<input name="location" maxlength="190" value="${esc(j.location||'')}" placeholder="Rio de Janeiro · Presencial"></label></div><div class="split"><label class="check"><input type="checkbox" name="internal" ${j.internal?'checked':''}>Oportunidade interna</label><label class="check"><input type="checkbox" name="published" ${j.published?'checked':''}>Publicar no portal interno</label></div><div class="section-label">Critérios de análise · descrição e peso</div><div id="requirements">${(j.requirements||[]).map(requirementRow).join('')}</div><button type="button" data-action="add-req">＋ Adicionar requisito</button><p class="help">Critérios profissionais objetivos. Categorias: obrigatórios 60%, desejáveis 20%, experiência 10%, competências 10%; ausentes são redistribuídas. Não inclua características pessoais sensíveis.</p><div class="section-label">Triagem pelo WhatsApp</div><label>Perguntas padrão · uma por linha<textarea name="questions" rows="4" placeholder="Qual sua disponibilidade para iniciar?">${esc((j.questions||[]).join('\n'))}</textarea></label><label>Mensagem inicial personalizável<textarea name="message_template" maxlength="4000">${esc(j.message_template||'Olá, {nome}! Aqui é o RH do Grupo DDM. Você tem interesse em conversar sobre a vaga {vaga}? Responda SIM para iniciar ou SAIR para encerrar.')}</textarea></label><p class="help">Use {nome} e {vaga}. As perguntas começam após o candidato responder SIM. Inclua a opção SAIR.</p><div class="modal-foot"><button type="button" data-action="close">Cancelar</button><button class="primary" type="submit">Salvar oportunidade</button></div></form>`);}
async function extractJob(type,button){const form=$('#job-form');button.disabled=true;const old=button.textContent;button.textContent='Lendo e estruturando…';try{const d=await api('/jobs/extract',json('POST',{source_type:type,job_url:form.elements.source_url.value||null,description_text:form.elements.description.value||null}));if(d.title)form.elements.title.value=d.title;form.elements.description.value=d.description;form.elements.openings.value=d.openings||'';$('#requirements').innerHTML=d.requirements.map(requirementRow).join('');toast(d.source==='openai'?'Extraído com IA. Revise antes de salvar.':'Extração preliminar. Revise cada requisito; OpenAI não configurada.');}finally{button.disabled=false;button.textContent=old;}}
function candidate(id){const c=state.report.results.find(c=>c.id===Number(id));modal('Análise do candidato',`<h2>${esc(c.name)}</h2><p>${esc(currentJob().title)} · ${c.score} / 100 pontos</p><div class="notice info">${esc(c.evidences?.summary||'Revise as evidências antes de decidir.')}</div>${(c.evidences?.all||[]).map(e=>`<div class="evidence"><span class="eyebrow">${esc(e.category)}</span>${pill(e.status,e.status==='Atende'?'green':'orange')}<h3>${esc(e.req)}</h3><p>${esc(e.detail)}</p></div>`).join('')}<form id="contact-form" data-id="${c.candidate_id}"><div class="section-label">Confirme os dados antes da convocação</div><label>Nome<input name="name" value="${esc(c.name)}" required></label><div class="split"><label>E-mail<input name="email" type="email" value="${esc(c.email||'')}"></label><label>WhatsApp com DDD<input name="phone" value="${esc(c.phone||'')}" required placeholder="21999999999"></label></div><button class="primary">Salvar contato</button></form>`);}
function newSlot(){modal('Disponibilizar horário',`<form id="slot-form"><label>E-mail do responsável no Microsoft 365<input name="recruiter" type="email" required value="${esc(state.user.email)}" maxlength="190"></label><div class="split"><label>Início<input name="starts_at" type="datetime-local" required></label><label>Fim<input name="ends_at" type="datetime-local" required></label></div><label>Local ou link da entrevista<input name="location" required maxlength="255" placeholder="Unidade DDM ou link da reunião"></label><p class="help">Fuso do navegador: ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}.</p><button class="primary">Salvar disponibilidade</button></form>`);}
function bookSlot(id){const options=state.conversations.filter(c=>c.status==='completed');modal('Reservar entrevista',options.length?`<form id="booking-form" data-id="${id}"><label>Candidato com triagem concluída<select name="conversation_id">${options.map(c=>`<option value="${c.id}">${esc(c.name)} · ${esc(c.job)}</option>`).join('')}</select></label><p class="help">Confirme a disponibilidade com o candidato. A reserva é interna; não cria convite no Outlook nem envia mensagem.</p><button class="primary">Confirmar reserva</button></form>`:empty('Nenhuma triagem concluída','Conclua as perguntas antes de reservar uma entrevista.'));}
function login(){$('#app').innerHTML=`<div class="login-layout"><section class="login-story">${brand()}<h1>Talento que conecta.<br><em>Futuro que acontece.</em></h1><p>Um espaço para descobrir potencial, aproximar pessoas e construir os próximos capítulos do Grupo DDM.</p></section><section class="login-form"><div><span class="eyebrow">Workspace de recrutamento</span><h2>Bem-vindo ao DDM Pessoas.</h2><p>Entre para acompanhar suas oportunidades e candidatos.</p><form id="login-form"><label>E-mail do RH<input type="email" name="email" autocomplete="username" required placeholder="seu.email@empresa.com.br"></label><label>Senha<input type="password" name="password" autocomplete="current-password" required></label><div class="error" id="login-error" role="alert"></div><button class="primary">Entrar no workspace →</button></form><a class="portal-link" href="/interno">Sou colaborador · Ver oportunidades internas ↗</a><p class="help">Primeiro acesso? Solicite à administração o cadastro da sua conta do RH.</p></div></section></div>`;}
async function portal(){const jobs=await api('/public/jobs');state.publicJobs=jobs;$('#app').innerHTML=`<header class="public-header">${brand()}<a href="/login" class="button">Área do RH →</a></header><main class="public-main"><section class="public-hero"><span class="eyebrow">Carreiras · Oportunidades internas</span><h1>Seu próximo capítulo<br>pode começar <em>aqui.</em></h1><p>Você já faz parte da nossa história. Conheça novas possibilidades no Grupo DDM e compartilhe com o RH onde quer chegar.</p><button class="primary" data-action="apply">Fazer parte do banco de talentos ↗</button></section><div class="heading"><div><h2>Oportunidades para crescer</h2><p>${jobs.length} vaga(s) interna(s) disponível(is)</p></div></div>${jobs.length?`<div class="public-grid">${jobs.map(j=>`<article class="job-card">${pill('Recrutamento interno','orange')}<h2>${esc(j.title)}</h2><div class="help">${esc(j.location||'Local a confirmar')} · ${j.openings?j.openings+' posição(ões)':'Quantidade a confirmar'}</div><p>${esc(j.description)}</p><button class="primary" data-action="apply" data-id="${j.id}">Quero me candidatar →</button></article>`).join('')}</div>`:empty('Novas oportunidades vêm por aí','Enquanto isso, deixe seu currículo atualizado no banco de talentos.','apply','Cadastrar meu currículo')}<div class="card portal-footer"><h2>Seu talento merece ser conhecido.</h2><p>Cadastre sua experiência e áreas de interesse. Seus dados e currículo serão acessados apenas pelo RH para recrutamento interno. Guarde o código recebido para atualizar seu cadastro.</p><button data-action="apply">Cadastrar ou atualizar meus dados</button></div><p class="footer">Grupo DDM · Pessoas e possibilidades</p></main>`;}
function applyForm(id){const j=state.publicJobs.find(j=>j.id===Number(id));modal(j?'Candidatar-se · '+j.title:'Banco de talentos internos',`<form id="application-form"><input type="hidden" name="job_id" value="${j?.id||''}"><label>Nome completo<input name="name" required maxlength="190" autocomplete="name"></label><div class="split"><label>E-mail<input name="email" type="email" required maxlength="190" autocomplete="email"></label><label>WhatsApp com DDD<input name="phone" type="tel" required maxlength="30" autocomplete="tel"></label></div><div class="split"><label>Matrícula<input name="employee_id" required maxlength="100"></label><label>Departamento<input name="department" required maxlength="190"></label></div><label>Cargo atual<input name="current_role" required maxlength="190"></label><label>Áreas de interesse<textarea name="interests" maxlength="2000" placeholder="Conte ao RH quais caminhos gostaria de explorar."></textarea></label><label class="file-upload">Currículo atualizado · PDF ou DOCX, até 8 MB<input name="file" type="file" accept=".pdf,.docx" required></label><label>Código de atualização (se já possui cadastro)<input name="update_token" autocomplete="off" placeholder="Deixe em branco para um novo cadastro" maxlength="100"></label><label class="check"><input type="checkbox" name="consent" required value="true">Autorizo o uso dos meus dados e currículo pelo RH do Grupo DDM para recrutamento interno e banco de talentos.</label><p class="help">Para corrigir ou solicitar a exclusão dos dados, procure o RH. A inscrição não garante entrevista ou contratação.</p><button class="primary">${j?'Enviar candidatura':'Salvar no banco de talentos'}</button></form>`);}
async function action(button){const a=button.dataset.action,id=button.dataset.id;
if(a==='close')return close();if(a==='nav'){if(button.dataset.tab==='exams')state.examView={mode:'list'};return navigate(button.dataset.tab);}if(a==='retry')return navigate(state.tab);if(a==='logout'){await api('/auth/logout',json('POST',{}));state.user=null;login();return;}
if(a==='new-job'||a==='edit-job')return editJob(id);if(a==='analyze-job'){state.jobId=Number(id);return navigate('ranking');}if(a==='go-ranking')return navigate('ranking');if(a==='add-req')return $('#requirements').insertAdjacentHTML('beforeend',requirementRow());if(a==='remove-req')return button.closest('.req').remove();if(a==='extract-url'||a==='extract-text')return extractJob(a==='extract-url'?'url':'text',button);
if(a==='run-analysis'){button.disabled=true;button.textContent='Analisando currículos…';try{state.report=await api(`/jobs/${state.jobId}/screenings`,json('POST',{}));renderRanking();toast('Análise concluída e salva.');}finally{button.disabled=false;button.textContent='✧ Executar análise';}return;}
if(a==='candidate')return candidate(id);if(a==='select-best'){const top=new Set(state.report.results.slice(0,currentJob().openings).map(c=>String(c.candidate_id)));document.querySelectorAll('.candidate-select').forEach(c=>c.checked=top.has(c.value));toast('Sugestão selecionada. Revise as evidências e os contatos antes de convocar.');return;}
if(a==='prepare-shortlist'){const ids=[...document.querySelectorAll('.candidate-select:checked')].map(c=>Number(c.value));if(!ids.length)throw Error('Selecione ao menos um candidato.');state.selection=ids;modal('Revisar convocações',`<p>Você está preparando ${ids.length} mensagem(ns) para ${esc(currentJob().title)}.</p><div class="bubble">${esc(currentJob().message_template)}</div><p class="help">Edite as perguntas e a mensagem em Gestão de vagas. Revise contatos e evidências de cada selecionado.</p><form id="shortlist-form"><label class="check"><input type="checkbox" required>Revisei os candidatos e autorizo preparar estas convocações.</label><button class="primary">Adicionar à fila do WhatsApp</button></form>`);return;}
if(a==='send-message'){button.disabled=true;try{const r=await api(`/outbox/${id}/send`,json('POST',{}));toast(r.error||'Mensagem aceita pelo provedor. Entrega ainda não confirmada.');await navigate('whatsapp');}finally{button.disabled=false;}return;}
if(a==='new-slot')return newSlot();if(a==='book-slot')return bookSlot(id);if(a==='apply')return applyForm(id);
if(a==='my-password')return myPassword();
if(a==='new-account')return editAccount();if(a==='edit-account')return editAccount(id);
if(a==='reset-password')return resetPassword(id,button.dataset.name);
if(a==='delete-account')return confirmDelete('Excluir acesso',`A conta de <strong>${esc(button.dataset.name)}</strong> sera removida e as sessoes abertas dela serao encerradas. O historico de auditoria permanece.`,`/accounts/${id}`);
if(a==='build-exam')return buildExam();if(a==='new-exam')return editExam();if(a==='edit-exam')return editExam(id);
if(a==='exam-attempts'){state.examView={mode:'attempts',examId:Number(id)};return render();}
if(a==='exam-grade'){state.examView={mode:'grade',attemptId:Number(id)};return render();}
if(a==='exam-back'){state.examView={mode:'list'};return render();}
if(a==='exam-back-attempts'){state.examView={mode:'attempts',examId:Number(id)};return render();}
if(a==='toggle-exam'){const open=!!button.dataset.open;await api(`/exams/${id}/open`,json('POST',{open}));await render();return toast(open?'Prova aberta. Chame o candidato na tela /prova.':'Prova fechada para novas aplicações.');}
if(a==='ai-review'){button.disabled=true;button.textContent='Consultando a IA…';try{const r=await api(`/attempts/${id}/ai-review`,json('POST',{}));await render();toast(r.message);}finally{button.disabled=false;}return;}
if(a==='add-question')return $('#questions').insertAdjacentHTML('beforeend',questionRow());
if(a==='remove-question')return button.closest('.qrow').remove();
if(a==='add-opt')return button.closest('.q-body').querySelector('.opts').insertAdjacentHTML('beforeend',optionRow('',false,button.closest('.qrow').dataset.uid));
if(a==='remove-opt')return button.closest('.opt').remove();
if(a==='add-crit')return button.closest('.q-body').querySelector('.crits').insertAdjacentHTML('beforeend',critRow({}));
if(a==='remove-crit')return button.closest('.crit').remove();
if(a==='exam-begin')return examIdentify(id);
if(a==='delete-job')return confirmDelete('Excluir vaga',`A vaga <strong>${esc(button.dataset.title)}</strong> sera excluida com os requisitos, os curriculos enviados e as analises salvas. Os arquivos saem do disco. Nao ha como desfazer.`,`/jobs/${id}`);
if(a==='delete-resume')return confirmDelete('Excluir curriculo',`O curriculo de <strong>${esc(button.dataset.name)}</strong> sera excluido, junto com o arquivo e as analises dele. Nao ha como desfazer.`,`/jobs/${state.jobId}/resumes/${id}`);
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)action(b).catch(err=>toast(err.message));});
document.addEventListener('input',e=>{if(e.target.closest('#exam-form'))scheduleSave();const v=e.target.value.toLocaleLowerCase('pt-BR');if(e.target.id==='job-search')$('#job-list').innerHTML=jobsList(state.jobs.filter(j=>(j.title+' '+j.location).toLocaleLowerCase('pt-BR').includes(v)));if(e.target.id==='talent-search')$('#talent-list').innerHTML=talentList(state.talents.filter(t=>(t.name+' '+t.department+' '+t.current_role+' '+t.employee_id).toLocaleLowerCase('pt-BR').includes(v)));if(e.target.id==='ranking-search')$('#ranking-list').innerHTML=rankingList(state.report.results.filter(c=>c.name.toLocaleLowerCase('pt-BR').includes(v)));});
document.addEventListener('change',async e=>{try{if(e.target.closest('#exam-form')){scheduleSave();return;}if(e.target.id==='build-template'){const mix=$('#build-mix');if(mix)mix.hidden=!!e.target.value;return;}if(e.target.classList.contains('q-kind')){const row=e.target.closest('.qrow');row.querySelector('.q-body').innerHTML=questionBody(e.target.value,{},row.dataset.uid);return;}if(e.target.id==='ranking-job'){state.jobId=Number(e.target.value);await render();}if(e.target.id==='resume-upload'){const files=[...e.target.files];if(!files.length)return;const form=new FormData();files.forEach(f=>form.append('files',f));toast('Recebendo e lendo currículos…');await api(`/jobs/${state.jobId}/resumes/upload`,{method:'POST',body:form});await render();toast('Currículos recebidos. Execute a análise para atualizar o ranking.');}}catch(err){toast(err.message);}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button[type="submit"],button.primary');if(b)b.disabled=true;try{
if(f.id==='login-form'){state.user=await api('/auth/login',json('POST',{email:f.elements.email.value,password:f.elements.password.value}));await navigate('overview');}
if(f.id==='job-form'){const data=Object.fromEntries(new FormData(f));data.openings=data.openings?Number(data.openings):null;data.internal=f.elements.internal.checked;data.published=f.elements.published.checked;data.questions=data.questions.split('\n').map(q=>q.trim()).filter(Boolean);data.requirements=[...f.querySelectorAll('.req')].map(row=>({category:row.querySelector('.req-category').value,title:row.querySelector('.req-title').value,weight:Number(row.querySelector('.req-weight').value)}));data.source_url=data.source_url||null;const j=await api('/jobs'+(f.dataset.id?'/'+f.dataset.id:''),json(f.dataset.id?'PUT':'POST',data));state.jobId=j.id;close();await navigate('jobs');toast('Vaga salva.');}
if(f.id==='contact-form'){await api('/candidates/'+f.dataset.id,json('PUT',Object.fromEntries(new FormData(f))));close();await render();toast('Contato atualizado.');}
if(f.id==='shortlist-form'){const r=await api(`/jobs/${state.jobId}/shortlist`,json('POST',{candidate_ids:state.selection,reviewed:true}));close();await navigate('whatsapp');toast(r.message);}
if(f.id==='slot-form'){const d=Object.fromEntries(new FormData(f));d.starts_at=new Date(d.starts_at).toISOString();d.ends_at=new Date(d.ends_at).toISOString();await api('/calendar/slots',json('POST',d));close();await navigate('calendar');toast('Disponibilidade salva.');}
if(f.id==='booking-form'){await api(`/calendar/slots/${f.dataset.id}/book`,json('POST',{conversation_id:Number(f.elements.conversation_id.value)}));close();await navigate('calendar');toast('Entrevista reservada.');}
if(f.id==='account-form'){const d=Object.fromEntries(new FormData(f));
if(f.dataset.id){await api('/accounts/'+f.dataset.id,json('PUT',{name:d.name,role:d.role,active:d.active==='1'}));}
else{await api('/accounts',json('POST',{name:d.name,email:d.email,password:d.password,role:d.role}));}
close();await render();toast(f.dataset.id?'Acesso atualizado.':'Acesso criado.');}
if(f.id==='reset-form'){const r=await api(`/accounts/${f.dataset.id}/password`,json('POST',{new_password:f.elements.new_password.value}));close();await render();toast(r.message);}
if(f.id==='my-password-form'){const r=await api('/auth/password',json('POST',{current_password:f.elements.current_password.value,new_password:f.elements.new_password.value}));close();toast(r.message);}
if(f.id==='delete-form'){const r=await api(f.dataset.path,{method:'DELETE'});close();await navigate(state.tab);toast(r.resumes_removed!==undefined?`Vaga excluida (${r.resumes_removed} curriculo(s) removido(s)).`:'Curriculo excluido.');}
if(f.id==='exam-build-form'){const d=Object.fromEntries(new FormData(f));
const body={title:d.title,job_id:d.job_id?Number(d.job_id):null,level:d.level,mode:d.mode,area:'',duration_minutes:Number(d.duration_minutes)||60,access_code:d.access_code||'',template:d.template||null,mix:[...f.querySelectorAll('.mix-amount')].map(i=>({subject:i.dataset.subject,amount:Number(i.value)||0})).filter(x=>x.amount>0)};
const saved=await api('/exams/build',json('POST',body));close();await render();toast(`Prova montada com ${saved.questions_count} questao(oes). Revise antes de abrir.`);}
if(f.id==='exam-builder'){const d=Object.fromEntries(new FormData(f));const body={title:d.title,job_id:d.job_id?Number(d.job_id):null,instructions:d.instructions,duration_minutes:Number(d.duration_minutes),level:d.level||'junior',mode:d.mode||'online',area:d.area||'',access_code:d.access_code||'',questions:collectQuestions(f)};
const saved=f.dataset.id?await api('/exams/'+f.dataset.id,json('PUT',body)):await api('/exams',json('POST',body));close();await render();toast(`Prova salva com ${saved.questions_count} questao(oes).`);}
if(f.id==='grade-form'){const items=[...f.querySelectorAll('.rubric')].map(r=>({question_id:Number(r.dataset.qid),scores:[...r.querySelectorAll('.grade-score')].map(x=>Number(x.value)||0),note:r.closest('.question').querySelector('.grade-note').value}));
const r=await api(`/attempts/${f.dataset.id}/grade`,json('POST',{items}));await render();toast(r.final_score!=null?`Correcao salva. Nota final ${r.final_score}.`:'Correcao salva.');}
if(f.id==='exam-start-form'){const d=Object.fromEntries(new FormData(f));d.consent=true;state.sitting=await api(`/public/exams/${f.dataset.id}/start`,json('POST',d));close();examSitting();}
if(f.id==='exam-form'){await submitExam(false);return;}
if(f.id==='application-form'){const data=new FormData(f);if(!data.get('job_id'))data.delete('job_id');const r=await api('/public/apply',{method:'POST',body:data});close();modal('Seu próximo capítulo já começou.',`<div class="notice info">${esc(r.message)}</div><label>Seu código privado de atualização<input readonly value="${esc(r.update_token)}" aria-label="Código privado de atualização"></label><p class="help">Copie e guarde este código em um local seguro. Ele permite atualizar seus dados. Não compartilhe com terceiros.</p><div class="modal-foot"><button data-action="close" class="primary">Concluir</button></div>`);}
}catch(err){if(f.id==='login-form')$('#login-error').textContent=err.message;else toast(err.message);}finally{if(b)b.disabled=false;}});

async function buildExam(){const lib=await api('/exam-library');state.library=lib;
modal('Montar prova da biblioteca',`<form id="exam-build-form"><p class="help">${lib.subjects.reduce((s,x)=>s+x.total,0)} questoes disponiveis em ${lib.subjects.length} materias. As questoes entram com gabarito e rubrica prontos, e voce pode editar depois.</p><label>Modelo<select name="template" id="build-template"><option value="">Montar por materia</option>${lib.templates.map(t=>`<option value="${t.key}">${esc(t.title)} — ${t.questions} questoes, ${t.duration_minutes} min</option>`).join('')}</select></label><label>Titulo da prova<input name="title" required maxlength="190" placeholder="Prova — Analista de DP"></label><label>Vaga vinculada<select name="job_id"><option value="">Sem vinculo</option>${state.jobs.map(j=>`<option value="${j.id}">${esc(j.title)}</option>`).join('')}</select></label><div class="split"><label>Nivel<select name="level">${lib.levels.map(l=>`<option value="${l.key}" ${l.key==='junior'?'selected':''}>${esc(l.label)}</option>`).join('')}</select></label><label>Duracao em minutos<input name="duration_minutes" type="number" min="5" max="600" value="60"></label></div><div class="split"><label>Aplicacao<select name="mode"><option value="online" selected>Online</option><option value="presencial">Presencial</option></select></label><label>Codigo de acesso<input name="access_code" maxlength="40" placeholder="Opcional"></label></div><div id="build-mix"><div class="card-head"><div><h2>Materias</h2><p>Quantas questoes de cada uma</p></div></div><div class="mix">${lib.subjects.map(x=>`<label class="mix-row"><span>${esc(x.label)}<small>${x.total} disponiveis</small></span><input class="mix-amount" data-subject="${x.key}" type="number" min="0" max="50" value="0"></label>`).join('')}</div></div><button class="primary">Montar prova</button></form>`);}

/* ------------------------------------------------------------- usuarios */
const ROLES={admin:'Administrador',rh:'Recursos humanos'};
async function renderAccounts(){state.accounts=await api('/accounts');
$('#main').innerHTML=heading('Quem tem acesso ao workspace','Contas do RH, papeis e redefinicao de senha.','<button class="primary" data-action="new-account">＋ Novo usuario</button>')+`<div class="notice">O administrador gerencia as contas. Quem tem papel de recursos humanos usa o sistema, mas nao cria nem remove acessos. Toda alteracao fica registrada na auditoria.</div><div class="card">${accountsList(state.accounts)}</div>`;}
function accountsList(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Pessoa</th><th>Papel</th><th>Situacao</th><th>Ultimo acesso</th><th></th></tr></thead><tbody>${rows.map(a=>`<tr><td><strong>${esc(a.name)}</strong>${esc(a.email)}${a.id===state.user.id?' '+pill('voce','orange'):''}</td><td>${esc(ROLES[a.role]||a.role)}</td><td>${a.active?pill('Ativa','green'):pill('Desativada')}</td><td>${a.last_login_at?date(a.last_login_at+'Z'):'—'}</td><td class="actions"><button class="small" data-action="edit-account" data-id="${a.id}">Editar</button><button class="small" data-action="reset-password" data-id="${a.id}" data-name="${esc(a.name)}">Redefinir senha</button>${a.id===state.user.id?'':`<button class="small danger" data-action="delete-account" data-id="${a.id}" data-name="${esc(a.name)}">Excluir</button>`}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma conta cadastrada','Crie o primeiro acesso do time.','new-account','Novo usuario');}
function editAccount(id){const a=(state.accounts||[]).find(x=>x.id===Number(id));
modal(a?'Editar acesso':'Novo usuario',`<form id="account-form" data-id="${a?a.id:''}"><label>Nome completo<input name="name" required minlength="3" maxlength="190" value="${a?esc(a.name):''}"></label>${a?'':'<label>E-mail<input name="email" type="email" required maxlength="190" autocomplete="off"></label>'}<div class="split"><label>Papel<select name="role">${Object.entries(ROLES).map(([k,l])=>`<option value="${k}" ${(a?a.role:'rh')===k?'selected':''}>${l}</option>`).join('')}</select></label>${a?`<label>Situacao<select name="active"><option value="1" ${a.active?'selected':''}>Ativa</option><option value="0" ${a.active?'':'selected'}>Desativada</option></select></label>`:''}</div>${a?'':'<label>Senha inicial<input name="password" type="password" required minlength="12" maxlength="200" autocomplete="new-password"></label><p class="help">Minimo de 12 caracteres. Entregue pessoalmente e peca a troca no primeiro acesso.</p>'}<button class="primary">${a?'Salvar':'Criar acesso'}</button></form>`);}
function resetPassword(id,nome){modal('Redefinir senha',`<div class="notice">A senha de <strong>${esc(nome)}</strong> sera substituida e todas as sessoes abertas dessa conta serao encerradas.</div><form id="reset-form" data-id="${id}"><label>Nova senha<input name="new_password" type="password" required minlength="12" maxlength="200" autocomplete="new-password"></label><p class="help">Minimo de 12 caracteres.</p><button class="primary">Redefinir</button></form>`);}
function myPassword(){modal('Minha senha',`<form id="my-password-form"><label>Senha atual<input name="current_password" type="password" required maxlength="200" autocomplete="current-password"></label><label>Nova senha<input name="new_password" type="password" required minlength="12" maxlength="200" autocomplete="new-password"></label><p class="help">Minimo de 12 caracteres. As outras sessoes abertas serao encerradas.</p><button class="primary">Alterar senha</button></form>`);}

function confirmDelete(title,body,path){modal(title,`<div class="notice danger-notice">${body}</div><form id="delete-form" data-path="${esc(path)}"><label class="check"><input type="checkbox" required>Confirmo que quero excluir e entendo que nao da para voltar atras.</label><button class="primary danger">Excluir definitivamente</button></form>`);}

/* ----------------------------------------------------------------- provas */
const LEVELS={operacional:'Operacional',junior:'J\u00fanior / assistente',pleno:'Pleno / analista',senior:'S\u00eanior / especialista'};
const MODES={online:'Online',presencial:'Presencial'};
const KINDS={choice:'Múltipla escolha',truefalse:'Verdadeiro ou falso',matching:'Associação',essay:'Discursiva / redação'};
let qseq=0,examTimer=null,saveTimer=null;
const examCell=r=>r.exam_score==null?'<span class="muted-cell">—</span>':`<span class="score">${r.exam_score.toFixed(1)}</span>${r.exam_status==='submitted'?'<div class="help">parcial</div>':''}`;
async function renderExams(){const view=state.examView||(state.examView={mode:'list'});
if(view.mode==='grade'){state.attempt=await api('/attempts/'+view.attemptId);return renderGrade();}
if(view.mode==='attempts'){[state.exam,state.attempts]=await Promise.all([api('/exams/'+view.examId),api(`/exams/${view.examId}/attempts`)]);return renderAttempts();}
state.exams=await api('/exams');
$('#main').innerHTML=heading('Provas que mostram o que a pessoa sabe','Aplicação presencial, na máquina do RH. As objetivas corrigem sozinhas; a redação é sua.','<button data-action="build-exam">✧ Montar da biblioteca</button><button class="primary" data-action="new-exam">＋ Nova prova</button>')+`<div class="notice">Prova de conhecimento e habilidade o RH aplica sozinho. Teste psicológico ou de personalidade exige psicólogo inscrito no CRP e instrumento aprovado no SATEPSI — não cadastre esse tipo de prova aqui.</div><div class="card"><div class="toolbar"><a class="button" href="/prova" target="_blank" rel="noopener">Abrir a tela do candidato ↗</a><span class="help">Deixe essa tela aberta no computador em que o candidato vai fazer a prova.</span></div>${examsList(state.exams)}</div>`;}
function examsList(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Prova</th><th>Perfil</th><th>Vaga</th><th>Questões</th><th>Aplicações</th><th>Situação</th><th></th></tr></thead><tbody>${rows.map(e=>`<tr><td><strong>${esc(e.title)}</strong><br>${e.duration_minutes} minutos</td><td>${esc(LEVELS[e.level]||e.level||'')}<br><span class="help">${esc(MODES[e.mode]||e.mode||'')}${e.access_code?' · com código':''}</span></td><td>${esc(e.job||'Sem vaga vinculada')}</td><td>${e.questions_count}</td><td>${e.attempts_count}${e.pending_review?' · '+pill(e.pending_review+' a corrigir','orange'):''}</td><td>${e.open?pill('Aberta','green'):pill('Fechada')}</td><td class="actions"><button class="small" data-action="exam-attempts" data-id="${e.id}">Resultados →</button><button class="small" data-action="edit-exam" data-id="${e.id}">Editar</button><button class="small" data-action="toggle-exam" data-id="${e.id}" data-open="${e.open?'':'1'}">${e.open?'Fechar':'Abrir'}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma prova cadastrada','Monte a primeira prova para aplicar presencialmente.','new-exam','Criar prova');}
function renderAttempts(){const e=state.exam;
$('#main').innerHTML=heading(esc(e.title),`${e.questions.length} questão(ões) · ${e.duration_minutes} minutos${e.job?' · '+esc(e.job):''}`,`<button class="quiet" data-action="exam-back">← Todas as provas</button>`)+`<div class="card"><div class="toolbar">${e.open?pill('Aberta para aplicação','green'):pill('Fechada')}<button class="small" data-action="toggle-exam" data-id="${e.id}" data-open="${e.open?'':'1'}">${e.open?'Fechar aplicação':'Abrir aplicação'}</button><a class="button small" href="/prova" target="_blank" rel="noopener">Tela do candidato ↗</a></div>${state.attempts.length?`<div class="table-wrap"><table><thead><tr><th>Candidato</th><th>Entrega</th><th>Objetiva</th><th>Nota final</th><th>Situação</th><th></th></tr></thead><tbody>${state.attempts.map(a=>`<tr><td><strong>${esc(a.name)}</strong>${esc(a.email||'')}<br>${esc(a.phone||'')}${a.document?' · '+esc(a.document):''}</td><td>${a.submitted_at?date(a.submitted_at+'Z'):'Em andamento'}</td><td>${a.objective_score??'—'}</td><td><strong>${a.final_score??'—'}</strong></td><td>${a.status==='graded'?pill('Corrigida','green'):a.status==='submitted'?pill('Aguarda correção','orange'):pill('Em andamento')}</td><td>${a.status==='in_progress'?'':`<button class="small" data-action="exam-grade" data-id="${a.id}">Corrigir →</button>`}</td></tr>`).join('')}</tbody></table></div>`:empty('Ninguém fez esta prova ainda','Abra a aplicação e chame o candidato na tela /prova.')}</div>`;}
function responseText(q){const r=q.response;
if(r===null||r===undefined||r==='')return '<em class="muted-cell">Sem resposta</em>';
if(q.kind==='choice')return esc((q.options||[])[r]??'—');
if(q.kind==='truefalse')return r?'Verdadeiro':'Falso';
if(q.kind==='matching')return (q.options?.left||[]).map((l,i)=>`${esc(l)} → ${esc((q.options?.right||[])[r[i]]??'—')}`).join('<br>');
return esc(r).replace(/\n/g,'<br>');}
function keyText(q){
if(q.kind==='choice')return esc((q.options||[])[q.answer_key]??'—');
if(q.kind==='truefalse')return q.answer_key?'Verdadeiro':'Falso';
if(q.kind==='matching')return (q.options?.left||[]).map((l,i)=>`${esc(l)} → ${esc((q.options?.right||[])[(q.answer_key||[])[i]]??'—')}`).join('<br>');
return '';}
function renderGrade(){const a=state.attempt;
$('#main').innerHTML=heading(esc(a.name),`${esc(a.exam.title)} · ${a.submitted_at?'entregue em '+date(a.submitted_at+'Z'):'em andamento'}`,`<button class="quiet" data-action="exam-back-attempts" data-id="${a.exam_id}">← Voltar</button>`)+`<div class="metrics"><div class="metric"><span>Objetiva</span><strong>${a.objective_score??'—'}</strong><small>de 100, automática</small></div><div class="metric accent"><span>Nota final</span><strong>${a.final_score??'—'}</strong><small>${a.status==='graded'?'Corrigida pelo RH':'Aguarda correção das discursivas'}</small></div><div class="metric"><span>Contato informado</span><strong class="text-small">${esc(a.email||'—')}</strong><small>${esc(a.phone||'')}</small></div><div class="metric"><span>Documento</span><strong class="text-small">${esc(a.document||'—')}</strong><small>Confirmar na aplicação</small></div></div><form id="grade-form" data-id="${a.id}">${a.questions.map(gradeQuestion).join('')}<div class="toolbar"><button class="primary">Salvar correção</button>${a.questions.some(q=>q.kind==='essay')?`<button type="button" data-action="ai-review" data-id="${a.id}">✧ Sugerir nota por IA</button>`:''}</div></form>`;}
function gradeQuestion(q,i){const objective=q.kind!=='essay';
return `<section class="question"><div class="q-head"><span class="q-num">${String(i+1).padStart(2,'0')}</span><div><strong>${esc(q.statement)}</strong><div class="help">${KINDS[q.kind]} · peso ${q.weight}</div></div>${objective?(q.correct?pill('Acertou','green'):q.awarded>0?pill('Parcial','orange'):pill('Errou')):pill('Correção do RH','orange')}</div><div class="split"><div><div class="label-small">Resposta do candidato</div><div class="answer">${responseText(q)}</div></div>${objective?`<div><div class="label-small">Gabarito</div><div class="answer">${keyText(q)}</div></div>`:''}</div>${objective?'':rubricFields(q)}</section>`;}
function rubricFields(q){const s=q.ai_suggestion;
return `${s?`<div class="notice info"><strong>Sugestão da IA${s.model?' · '+esc(s.model):''}</strong><p>${esc(s.summary||'')}</p>${(s.criteria||[]).map(c=>`<div class="help">${esc(c.name)}: ${c.score} de ${c.max}${c.quote?' · “'+esc(c.quote)+'”':''}</div>`).join('')}<p class="help">É uma sugestão. Vale a nota que você salvar.</p></div>`:''}<div class="rubric" data-qid="${q.id}">${(q.rubric||[]).map((c,i)=>`<label class="crit-grade">${esc(c.name)} <small>até ${c.max}</small><input class="grade-score" type="number" min="0" max="${c.max}" step="0.5" value="${s&&s.criteria&&s.criteria[i]?s.criteria[i].score:''}" placeholder="0"></label>`).join('')}</div><label>Observação do RH<textarea class="grade-note" maxlength="4000" rows="2">${esc(q.reviewer_note||'')}</textarea></label>`;}
async function editExam(id){const exam=id?await api('/exams/'+id):{title:'',job_id:null,instructions:'',duration_minutes:60,questions:[]};
modal(id?'Editar prova':'Nova prova',`<form id="exam-builder" data-id="${id||''}"><div class="split"><label>Título<input name="title" required maxlength="190" value="${esc(exam.title)}"></label><label>Duração em minutos<input name="duration_minutes" type="number" min="5" max="600" required value="${exam.duration_minutes}"></label></div><label>Vaga vinculada<select name="job_id"><option value="">Sem vínculo</option>${state.jobs.map(j=>`<option value="${j.id}" ${exam.job_id===j.id?'selected':''}>${esc(j.title)}</option>`).join('')}</select></label><div class="split"><label>Nível<select name="level">${Object.entries(LEVELS).map(([k,l])=>`<option value="${k}" ${(exam.level||'junior')===k?'selected':''}>${l}</option>`).join('')}</select></label><label>Aplicação<select name="mode">${Object.entries(MODES).map(([k,l])=>`<option value="${k}" ${(exam.mode||'online')===k?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="split"><label>Área ou cargo<input name="area" maxlength="120" value="${esc(exam.area||'')}" placeholder="Departamento pessoal"></label><label>Código de acesso<input name="access_code" maxlength="40" value="${esc(exam.access_code||'')}" placeholder="Opcional"></label></div><p class="help">Na prova online, o código impede que qualquer pessoa com o link comece a prova. Deixe em branco para dispensar.</p><p class="help">Vincular a uma vaga faz a nota aparecer no ranking daquele processo, em coluna separada da aderência do currículo.</p><label>Instruções ao candidato<textarea name="instructions" rows="2" maxlength="8000">${esc(exam.instructions||'')}</textarea></label><div class="card-head"><div><h2>Questões</h2><p>O peso define quanto cada questão vale na nota.</p></div><button type="button" class="small" data-action="add-question">＋ Questão</button></div><div id="questions">${(exam.questions||[]).map(q=>questionRow(q)).join('')}</div><button class="primary">Salvar prova</button></form>`);}
const optionRow=(text,checked,uid)=>`<label class="opt"><input type="radio" name="key-${uid}" ${checked?'checked':''}><input class="opt-text" value="${esc(text)}" placeholder="Alternativa" maxlength="500"><button type="button" class="quiet small" data-action="remove-opt" aria-label="Remover alternativa">✕</button></label>`;
const critRow=c=>`<div class="crit"><input class="crit-name" value="${esc(c.name||'')}" placeholder="Critério de correção" maxlength="120"><input class="crit-max" type="number" min="0.5" max="100" step="0.5" value="${c.max??5}" aria-label="Pontos do critério"><button type="button" class="quiet small" data-action="remove-crit" aria-label="Remover critério">✕</button></div>`;
const pairsText=q=>((q.options&&q.options.left)||[]).map((l,i)=>`${l} = ${((q.options&&q.options.right)||[])[(q.answer_key||[])[i]]??''}`).join('\n');
function questionBody(kind,q,uid){q=q||{};
if(kind==='choice'){const opts=q.options&&q.options.length?q.options:['',''];return `<div class="opts">${opts.map((o,i)=>optionRow(o,q.answer_key===i,uid)).join('')}</div><button type="button" class="small" data-action="add-opt">＋ Alternativa</button><p class="help">Marque o círculo da alternativa correta.</p>`;}
if(kind==='truefalse')return `<label>Resposta correta<select class="q-tf"><option value="true" ${q.answer_key===true?'selected':''}>Verdadeiro</option><option value="false" ${q.answer_key===false?'selected':''}>Falso</option></select></label>`;
if(kind==='matching')return `<label>Pares, um por linha, no formato <strong>item = correspondente</strong><textarea class="q-pairs" rows="4" placeholder="Fundo de garantia = FGTS">${esc(pairsText(q))}</textarea></label><p class="help">A ordem do lado direito é embaralhada para o candidato.</p>`;
const rubric=q.rubric&&q.rubric.length?q.rubric:[{name:'Clareza e organização',max:5},{name:'Domínio do tema',max:5}];
return `<div class="crits">${rubric.map(critRow).join('')}</div><button type="button" class="small" data-action="add-crit">＋ Critério</button><p class="help">A IA pode sugerir a nota por critério; a nota final é sempre do RH.</p>`;}
function questionRow(q){q=q||{kind:'choice',statement:'',weight:1,options:['','']};const uid='q'+(++qseq);
return `<div class="qrow" data-uid="${uid}"><div class="q-top"><select class="q-kind" aria-label="Tipo de questão">${Object.entries(KINDS).map(([k,l])=>`<option value="${k}" ${q.kind===k?'selected':''}>${l}</option>`).join('')}</select><label class="weight">Peso<input class="q-weight" type="number" min="0.5" max="10" step="0.5" value="${q.weight||1}"></label><button type="button" class="quiet small" data-action="remove-question" aria-label="Remover questão">✕</button></div><textarea class="q-statement" rows="2" placeholder="Enunciado da questão" maxlength="8000">${esc(q.statement||'')}</textarea><div class="q-body">${questionBody(q.kind,q,uid)}</div></div>`;}
function collectQuestions(form){return [...form.querySelectorAll('.qrow')].map(row=>{const kind=row.querySelector('.q-kind').value;
const q={kind,statement:row.querySelector('.q-statement').value.trim(),weight:Number(row.querySelector('.q-weight').value)||1};
if(kind==='choice'){const opts=[...row.querySelectorAll('.opt')];q.options=opts.map(o=>o.querySelector('.opt-text').value.trim());const key=opts.findIndex(o=>o.querySelector('input[type=radio]').checked);q.answer_key=key<0?null:key;}
else if(kind==='truefalse')q.answer_key=row.querySelector('.q-tf').value==='true';
else if(kind==='matching'){const pairs=row.querySelector('.q-pairs').value.split('\n').map(l=>l.split('=')).filter(x=>x.length>=2&&x[0].trim()&&x.slice(1).join('=').trim()).map(x=>[x[0].trim(),x.slice(1).join('=').trim()]);
const right=pairs.map(x=>x[1]),order=right.map((_,i)=>i);for(let i=order.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[order[i],order[j]]=[order[j],order[i]];}
q.options={left:pairs.map(x=>x[0]),right:order.map(i=>right[i])};q.answer_key=pairs.map((_,i)=>order.indexOf(i));}
else q.rubric=[...row.querySelectorAll('.crit')].map(c=>({name:c.querySelector('.crit-name').value.trim(),max:Number(c.querySelector('.crit-max').value)||1})).filter(c=>c.name);
return q;});}
/* ------------------------------------------------------- tela do candidato */
async function examPortal(){state.publicExams=await api('/public/exams');
$('#app').innerHTML=`<header class="public-header">${brand()}${pill('Ambiente de provas','orange')}</header><main class="public-main" id="exam-main"></main>`;
$('#exam-main').innerHTML=`<section class="public-hero"><span class="eyebrow">Processo seletivo · Grupo DDM</span><h1>Sua prova<br>começa <em>aqui.</em></h1><p>Confirme seus dados, leia as instruções e responda com calma. O tempo começa a contar quando você iniciar.</p></section>${state.publicExams.length?`<div class="public-grid">${state.publicExams.map(e=>`<article class="job-card">${pill('Prova','orange')}<h2>${esc(e.title)}</h2><div class="help">${e.duration_minutes} minutos${e.job?' · '+esc(e.job):''}${e.requires_code?' · exige código':''}</div><p>${esc(e.instructions||'')}</p><button class="primary" data-action="exam-begin" data-id="${e.id}">Iniciar →</button></article>`).join('')}</div>`:empty('Nenhuma prova aberta no momento','Procure a equipe de RH para liberar a sua prova.')}<p class="footer">Grupo DDM · Pessoas e possibilidades</p>`;}
function examIdentify(id){const prova=(state.publicExams||[]).find(x=>x.id===Number(id))||{};modal('Antes de começar',`<form id="exam-start-form" data-id="${id}"><p class="help">Seus dados e respostas são usados apenas neste processo seletivo, pelo RH do Grupo DDM.</p><label>Nome completo<input name="name" required minlength="3" maxlength="190" autocomplete="name"></label><div class="split"><label>E-mail<input name="email" type="email" required maxlength="190" autocomplete="email"></label><label>WhatsApp com DDD<input name="phone" type="tel" required maxlength="30" autocomplete="tel"></label></div><label>CPF ou matrícula<input name="document" maxlength="40"></label>${prova.requires_code?`<label>Código de acesso<input name="access_code" required maxlength="40" placeholder="Informado pelo RH"></label>`:''}<label class="check"><input type="checkbox" name="consent" required>Autorizo o uso dos meus dados e das minhas respostas neste processo seletivo.</label><p class="help">O cronômetro começa quando você confirmar.</p><button class="primary">Começar a prova</button></form>`);}
function examSitting(){const s=state.sitting;
$('#exam-main').innerHTML=`<div class="exam-head"><div><h1>${esc(s.title)}</h1><p class="help">${esc(s.instructions||'')}</p></div><div class="exam-timer" id="exam-timer">--:--</div></div><form id="exam-form">${s.questions.map(examQuestion).join('')}<div class="exam-foot"><p class="help">Suas respostas são salvas sozinhas enquanto você escreve. Depois de entregar não é possível alterar.</p><button class="primary">Entregar prova</button></div></form>`;
clearInterval(examTimer);examTimer=setInterval(tick,1000);tick();}
function examQuestion(q,i){let body='';
if(q.kind==='choice')body=(q.options||[]).map((o,k)=>`<label class="opt-pick"><input type="radio" name="q${q.id}" value="${k}"><span>${esc(o)}</span></label>`).join('');
else if(q.kind==='truefalse')body=[['true','Verdadeiro'],['false','Falso']].map(v=>`<label class="opt-pick"><input type="radio" name="q${q.id}" value="${v[0]}"><span>${v[1]}</span></label>`).join('');
else if(q.kind==='matching')body=((q.options&&q.options.left)||[]).map((l,k)=>`<div class="match"><span>${esc(l)}</span><select data-pos="${k}" aria-label="Correspondente"><option value="">Selecione</option>${((q.options&&q.options.right)||[]).map((r,ri)=>`<option value="${ri}">${esc(r)}</option>`).join('')}</select></div>`).join('');
else body=`<textarea rows="12" maxlength="20000" placeholder="Escreva sua resposta aqui"></textarea>`;
return `<section class="question" data-qid="${q.id}" data-kind="${q.kind}"><div class="q-head"><span class="q-num">${String(i+1).padStart(2,'0')}</span><div><strong>${esc(q.statement)}</strong><div class="help">${KINDS[q.kind]}</div></div></div>${body}</section>`;}
function tick(){const el=$('#exam-timer');if(!el||!state.sitting)return clearInterval(examTimer);
const left=Math.max(0,Math.floor((new Date(state.sitting.expires_at)-new Date())/1000));
el.textContent=String(Math.floor(left/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0');
el.classList.toggle('urgent',left<=120);
if(left<=0){clearInterval(examTimer);submitExam(true);}}
function collectSitting(){return [...document.querySelectorAll('#exam-form .question')].map(sec=>{const kind=sec.dataset.kind;let response=null;
if(kind==='choice'){const p=sec.querySelector('input:checked');response=p?Number(p.value):null;}
else if(kind==='truefalse'){const p=sec.querySelector('input:checked');response=p?p.value==='true':null;}
else if(kind==='matching')response=[...sec.querySelectorAll('select')].map(x=>x.value===''?-1:Number(x.value));
else response=sec.querySelector('textarea').value;
return {question_id:Number(sec.dataset.qid),response};});}
const examHeaders=()=>({'X-Exam-Token':state.sitting.token});
function scheduleSave(){clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{if(!state.sitting)return;
try{await api(`/public/attempts/${state.sitting.attempt_id}`,{...json('PUT',{answers:collectSitting()}),headers:examHeaders()});}catch(err){}},2500);}
async function submitExam(automatic){if(!state.sitting)return;clearInterval(examTimer);clearTimeout(saveTimer);
const payload={...json('POST',{answers:collectSitting()}),headers:examHeaders()};
try{const r=await api(`/public/attempts/${state.sitting.attempt_id}/submit`,payload);state.sitting=null;
$('#exam-main').innerHTML=`<section class="public-hero"><span class="eyebrow">Recebido</span><h1>Prova entregue.<br>Obrigado pelo seu <em>tempo.</em></h1><p>${esc(r.message||'')}${automatic?' O tempo terminou e suas respostas foram enviadas automaticamente.':''}</p></section><div class="card portal-footer"><h2>Pode chamar o RH.</h2><p>A equipe dará o retorno do processo seletivo pelos contatos que você informou. Sua nota não aparece nesta tela.</p></div>`;}
catch(err){toast(err.message);examTimer=setInterval(tick,1000);}}

(async()=>{try{if(location.pathname==='/interno')return await portal();if(location.pathname==='/prova')return await examPortal();try{state.user=await api('/auth/me');}catch{return login();}await navigate('overview');}catch(err){$('#app').innerHTML=`<div class="loading"><h1>Não foi possível conectar.</h1><p>${esc(err.message)}</p><a href="/" class="button">Tentar novamente</a></div>`;}})();
